const config = {
  external_key: 'tarot-78-arcanos-001',
  assembler_url: 'http://host.docker.internal:3001',
  target_duration_seconds: 30,
  visual_queries: [
    'antique tarot cards on a dark wooden table candlelight vertical',
    'hands arranging tarot cards close up dark study vertical',
    'antique tarot deck in occult library gold details vertical'
  ]
};

if (!config.external_key || config.visual_queries.length !== 3) {
  throw new Error('Configura una pieza y exactamente tres busquedas visuales.');
}

return [{ json: config }];

const row = $input.first().json;
const config = $('Seleccionar pieza').first().json;

if (!row.external_key) {
  throw new Error(`La pieza ${row.requested_key} no existe, no esta aprobada o no declara short_video.`);
}

const content = typeof row.generated_content === 'string'
  ? JSON.parse(row.generated_content)
  : row.generated_content;
const draft = content?.draft || {};
const slides = content?.visual?.slides || [];

for (const field of ['script', 'cta']) {
  if (typeof draft[field] !== 'string' || !draft[field].trim()) {
    throw new Error(`Falta draft.${field} aprobado.`);
  }
}
if (slides.length < 3) {
  throw new Error('Se requieren al menos tres slides visuales aprobados.');
}

const selectedSlides = [slides[0], slides[Math.floor(slides.length / 2)], slides.at(-1)];
const coverText = [selectedSlides[0]?.title, selectedSlides[0]?.body].filter(Boolean).join('. ');
const narration = [coverText, draft.script, draft.cta].filter(Boolean).join(' ').replace(/\s+/g, ' ').trim();
const wordCount = narration.split(/\s+/).filter(Boolean).length;
const estimatedDuration = Math.round((wordCount / 130) * 60);

if (estimatedDuration < 15 || estimatedDuration > 45) {
  throw new Error(`La narracion estima ${estimatedDuration}s; el gate admite 15-45s.`);
}

const sceneTexts = [coverText, draft.script, draft.cta];
const weights = sceneTexts.map(text => Math.max(1, text.split(/\s+/).filter(Boolean).length));
const totalWeight = weights.reduce((sum, value) => sum + value, 0);
let cursor = 0;
const scenes = sceneTexts.map((text, index) => {
  const isLast = index === sceneTexts.length - 1;
  const duration = isLast
    ? estimatedDuration - cursor
    : Math.max(3, Math.round((weights[index] / totalWeight) * estimatedDuration));
  const scene = {
    index,
    start_seconds: cursor,
    end_seconds: cursor + duration,
    duration_seconds: duration,
    narration: text,
    visual_query: config.visual_queries[index],
    slide_id: selectedSlides[index]?.id || `scene-${index + 1}`
  };
  cursor += duration;
  return scene;
});

return [{
  json: {
    workflow_contract: 'arcanum-video-short-preflight-v1',
    external_key: row.external_key,
    approval: { status: row.status, approved_at: row.approved_at, approved_by: row.approved_by },
    assembler_url: config.assembler_url,
    target: { format: 'vertical', width: 1080, height: 1920, fps: 30 },
    estimated_duration_seconds: estimatedDuration,
    narration,
    cta: draft.cta,
    scenes,
    visual_request: {
      segments: scenes.map(scene => ({ prompt: scene.visual_query, text: scene.narration })),
      orientation: 'portrait',
      min_width: 1080
    },
    audio_plan: {
      status: 'required',
      audio_url: null,
      voice_provider: null,
      voice_id: null,
      license_or_consent: null
    }
  }
}];

const plan = $('Construir storyboard').first().json;
const response = $input.first().json;
const items = Array.isArray(response.items) ? response.items : [];

if (items.length !== plan.scenes.length) {
  throw new Error(`Se esperaban ${plan.scenes.length} clips y llegaron ${items.length}. No se repetiran clips para ocultarlo.`);
}

const invalid = items.filter(item => !item.source || !item.author || !item.license || !item.video_path || !item.video_url || !item.slug);
if (invalid.length) {
  throw new Error('Uno o mas clips no incluyen fuente, autor, licencia, URL de origen, slug y archivo local.');
}

const blockers = ['Falta generar y aprobar el audio TTS con licencia o consentimiento.'];

return [{
  json: {
    status: 'needs_audio_review',
    render_ready: false,
    blockers,
    ...plan,
    visual_assets: items.map((item, index) => ({
      scene_index: index,
      source: item.source,
      author: item.author,
      license: item.license,
      source_url: item.video_url,
      source_slug: item.slug,
      local_path: item.video_path
    }))
  }
}];

const plan = $('Construir storyboard').first().json;
const health = $('Comprobar ensamblador').first().json;
return [{
  json: {
    status: 'blocked',
    render_ready: false,
    external_key: plan.external_key,
    blocker: health.pexels_configured === false
      ? 'El ensamblador responde, pero falta PEXELS_API_KEY.'
      : 'El ensamblador de video no responde en /healthz.',
    next_action: health.pexels_configured === false
      ? 'Configura una clave nueva de Pexels en marketing-automation/.env y reinicia video-assembler.'
      : 'Inicia el servicio video-assembler del compose y relanza este workflow.',
    storyboard: plan
  }
}];
